import React from 'react';
import { NavLink } from 'react-router-dom';

const Navbar = () => {
  const navStyles = {
    navbar: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      padding: '0',
      boxShadow: '0 4px 15px rgba(0, 0, 0, 0.1)',
      position: 'sticky',
      top: '0',
      zIndex: '1000'
    },
    navContainer: {
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '0 20px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      height: '70px'
    },
    navLogo: {
      color: 'white',
      fontSize: '1.8rem',
      fontWeight: 'bold',
      textShadow: '2px 2px 4px rgba(0, 0, 0, 0.3)'
    },
    navMenu: {
      display: 'flex',
      listStyle: 'none',
      margin: '0',
      padding: '0',
      gap: '10px'
    },
    navLink: {
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      color: 'white',
      textDecoration: 'none',
      padding: '12px 20px',
      borderRadius: '25px',
      transition: 'all 0.3s ease',
      fontWeight: '500',
      background: 'rgba(255, 255, 255, 0.1)',
      backdropFilter: 'blur(10px)',
      border: '1px solid rgba(255, 255, 255, 0.2)'
    },
    navLinkHover: {
      background: 'rgba(255, 255, 255, 0.2)',
      transform: 'translateY(-2px)',
      boxShadow: '0 5px 15px rgba(0, 0, 0, 0.2)'
    },
    navLinkActive: {
      background: 'rgba(255, 255, 255, 0.25)',
      boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
      border: '1px solid rgba(255, 255, 255, 0.4)'
    }
  };

  return (
    <nav style={navStyles.navbar}>
      <div style={navStyles.navContainer}>
        <div style={navStyles.navLogo}>
          <span>ReactLab</span>
        </div>
        <ul style={navStyles.navMenu}>
          {[
            { to: "/", icon: "🏠", text: "Home" },
            { to: "/about", icon: "ℹ️", text: "About" },
            { to: "/contact", icon: "📞", text: "Contact" },
            { to: "/product/1", icon: "🛍️", text: "Products" },
            { to: "/dashboard", icon: "🔒", text: "Dashboard" }
          ].map((item, index) => (
            <li key={index}>
              <NavLink 
                to={item.to}
                style={({ isActive }) => ({
                  ...navStyles.navLink,
                  ...(isActive && navStyles.navLinkActive)
                })}
                onMouseEnter={(e) => {
                  e.target.style.background = navStyles.navLinkHover.background;
                  e.target.style.transform = navStyles.navLinkHover.transform;
                  e.target.style.boxShadow = navStyles.navLinkHover.boxShadow;
                }}
                onMouseLeave={(e) => {
                  e.target.style.background = navStyles.navLink.background;
                  e.target.style.transform = 'none';
                  e.target.style.boxShadow = 'none';
                }}
              >
                <span>{item.icon}</span>
                {item.text}
              </NavLink>
            </li>
          ))}
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
